from decimal import Decimal, ROUND_HALF_EVEN

def format_success_rate(numerator: int, denominator: int) -> str:
    if not isinstance(denominator, int) or isinstance(denominator, bool):
        raise ValueError("denominator must be a positive int")
    if denominator <= 0:
        raise ValueError("denominator must be a positive int")

    if not isinstance(numerator, int) or isinstance(numerator, bool):
        raise ValueError("numerator must be an int")
    if numerator < 0 or numerator > denominator:
        raise ValueError("numerator must be in [0, denominator]")

    result = Decimal(numerator) / Decimal(denominator)
    rounded = result.quantize(Decimal('0.1'), rounding=ROUND_HALF_EVEN)
    return f"{rounded}%"
